-- Somente fixture sintética F8.4, nunca executar isoladamente em outro banco.
DO $$ BEGIN
  IF current_database() !~ '^tt_f84_[0-9a-f]{32}$' OR
     NOT EXISTS(SELECT 1 FROM tt_ensaio.identidade WHERE objetivo='F84-SINTETICO-DESCARTAVEL') THEN
    RAISE EXCEPTION 'Ambiente descartável não identificado';
  END IF;
END $$;
CREATE ROLE service_role NOLOGIN BYPASSRLS;
CREATE ROLE anon NOLOGIN; CREATE ROLE authenticated NOLOGIN;
CREATE TYPE public.usuarios_perfil_enum AS ENUM('participante','organizador','fornecedor','admin');
CREATE TABLE public.usuarios(id integer PRIMARY KEY,nome varchar(100) NOT NULL,email varchar(150) NOT NULL UNIQUE,perfil public.usuarios_perfil_enum NOT NULL);
INSERT INTO public.usuarios VALUES
 (7,'Organizador sintético','org7@example.invalid','organizador'),(8,'Fornecedor sintético','forn8@example.invalid','fornecedor'),
 (9,'Participante sintético','p9@example.invalid','participante'),(10,'Admin sintético','a10@example.invalid','admin'),
 (11,'Outro Organizador','org11@example.invalid','organizador'),(12,'Outro Admin','a12@example.invalid','admin'),
 (13,'Outro Fornecedor','forn13@example.invalid','fornecedor');
CREATE TABLE public.eventos(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,nome varchar(100) NOT NULL,data date NOT NULL,
 horario time NOT NULL,local varchar(200) NOT NULL,categoria varchar(100),publico integer NOT NULL,descricao text,status varchar(50),usuario_id integer NOT NULL REFERENCES public.usuarios(id));
CREATE TABLE public.inscricoes(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,usuario_id integer NOT NULL REFERENCES public.usuarios(id),
 evento_id integer NOT NULL REFERENCES public.eventos(id),status text NOT NULL DEFAULT 'Confirmada',UNIQUE(usuario_id,evento_id));
CREATE TABLE public.cotacoes(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,evento_id integer NOT NULL REFERENCES public.eventos(id),
 prazo date NOT NULL,modalidade text NOT NULL DEFAULT 'Fechada',observacoes text,status text NOT NULL DEFAULT 'Aberta',criada_em timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.propostas(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,cotacao_id integer NOT NULL REFERENCES public.cotacoes(id),
 fornecedor_id integer NOT NULL REFERENCES public.usuarios(id),valor numeric(12,2) NOT NULL,condicoes_pagamento text NOT NULL,detalhes_tecnicos text NOT NULL,
 status text NOT NULL DEFAULT 'Em avaliação',criada_em timestamptz NOT NULL DEFAULT now());
GRANT USAGE ON SCHEMA public TO service_role;
GRANT SELECT,UPDATE ON public.usuarios TO service_role;
GRANT SELECT,INSERT,UPDATE ON public.eventos,public.inscricoes,public.cotacoes,public.propostas TO service_role;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA public TO service_role;
